//! Golden files: regenerate them and review what changed (T11-015).
//!
//! Golden files (`testdata/golden`: images today, audio and simulation traces later) are
//! compared by tests and regenerated by running those tests with `UPDATE_GOLDEN=1`.
//! `cargo xtask golden update` does exactly that for every golden test target and then prints
//! a **review report**; `cargo xtask golden report` prints the report alone. The report compares
//! each changed file with the version in git `HEAD` so a reviewer sees *how much* an image
//! changed (mean and maximum channel difference, share of changed pixels, size changes) instead
//! of just "a binary file changed".

use std::path::Path;
use std::process::Command;

use anyhow::{Context, Result, bail};

use crate::guard::git;

/// The folder (relative to the repository root) that holds the golden files.
pub const GOLDEN_DIR: &str = "testdata/golden";

/// The test targets that regenerate goldens when `UPDATE_GOLDEN` is set: (package, test target).
pub const GOLDEN_TESTS: &[(&str, &str)] = &[("ss2-render", "golden_menu")];

/// How a golden file differs from git `HEAD`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Change {
    /// Not in `HEAD`.
    Added,
    /// In `HEAD` with other content.
    Modified,
    /// In `HEAD`, gone from the working tree.
    Deleted,
}

impl Change {
    fn label(self) -> &'static str {
        match self {
            Self::Added => "added",
            Self::Modified => "modified",
            Self::Deleted => "deleted",
        }
    }
}

/// One changed golden file.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Entry {
    /// Path relative to the repository root, with `/` separators.
    pub path: String,
    /// What changed.
    pub change: Change,
}

/// Read `git status --porcelain` output and keep the entries under `dir`. A rename counts as the
/// old file deleted and the new one added.
pub fn parse_status(porcelain: &str, dir: &str) -> Vec<Entry> {
    let prefix = format!("{dir}/");
    let unquote = |p: &str| -> String {
        p.strip_prefix('"')
            .and_then(|p| p.strip_suffix('"'))
            .unwrap_or(p)
            .to_owned()
    };
    let mut entries = Vec::new();
    for line in porcelain.lines() {
        let (Some(xy), Some(rest)) = (line.get(..2), line.get(3..)) else {
            continue;
        };
        let mut push = |path: String, change: Change| {
            if path.starts_with(&prefix) {
                entries.push(Entry { path, change });
            }
        };
        if xy.contains('R') {
            if let Some((old, new)) = rest.split_once(" -> ") {
                push(unquote(old), Change::Deleted);
                push(unquote(new), Change::Added);
            }
            continue;
        }
        let change = if xy == "??" || xy.contains('A') {
            Change::Added
        } else if xy.contains('D') {
            Change::Deleted
        } else {
            Change::Modified
        };
        push(unquote(rest), change);
    }
    entries
}

/// A decoded 8-bit RGBA image.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Rgba {
    /// Width in pixels.
    pub width: u32,
    /// Height in pixels.
    pub height: u32,
    /// `width * height * 4` bytes, row by row.
    pub pixels: Vec<u8>,
}

/// Decode a PNG (8-bit gray, gray+alpha, RGB or RGBA) to RGBA.
///
/// # Errors
/// The decoder's error for invalid data, or a message for palette and 16-bit images.
pub fn decode_png(bytes: &[u8]) -> Result<Rgba> {
    let mut reader = png::Decoder::new(std::io::Cursor::new(bytes))
        .read_info()
        .context("not a decodable PNG")?;
    let mut buf = vec![0; reader.output_buffer_size().context("PNG is too large")?];
    let info = reader
        .next_frame(&mut buf)
        .context("cannot decode the PNG")?;
    if info.bit_depth != png::BitDepth::Eight {
        bail!("only 8-bit PNGs are compared");
    }
    let data = &buf[..info.buffer_size()];
    let pixels = match info.color_type {
        png::ColorType::Rgba => data.to_vec(),
        png::ColorType::Rgb => data
            .chunks_exact(3)
            .flat_map(|p| [p[0], p[1], p[2], 255])
            .collect(),
        png::ColorType::Grayscale => data.iter().flat_map(|&g| [g, g, g, 255]).collect(),
        png::ColorType::GrayscaleAlpha => data
            .chunks_exact(2)
            .flat_map(|p| [p[0], p[0], p[0], p[1]])
            .collect(),
        png::ColorType::Indexed => bail!("palette PNGs are not compared"),
    };
    Ok(Rgba {
        width: info.width,
        height: info.height,
        pixels,
    })
}

/// How two images differ.
#[derive(Clone, Debug, PartialEq)]
pub enum ImageChange {
    /// Same size and same pixels (the file bytes may still differ, for example by compression).
    Same,
    /// The dimensions differ.
    Size {
        /// Old width and height.
        old: (u32, u32),
        /// New width and height.
        new: (u32, u32),
    },
    /// Same size, different pixels.
    Pixels {
        /// Mean absolute difference over all channels, `0.0..=255.0`.
        mean_abs: f64,
        /// Largest single-channel difference.
        max_abs: u8,
        /// Pixels with at least one channel different.
        changed: usize,
        /// All pixels.
        total: usize,
    },
}

/// Compare two images.
pub fn compare_images(old: &Rgba, new: &Rgba) -> ImageChange {
    if (old.width, old.height) != (new.width, new.height) {
        return ImageChange::Size {
            old: (old.width, old.height),
            new: (new.width, new.height),
        };
    }
    let (mut sum, mut max_abs, mut changed) = (0_u64, 0_u8, 0_usize);
    for (a, b) in old.pixels.chunks_exact(4).zip(new.pixels.chunks_exact(4)) {
        let mut differs = false;
        for (&x, &y) in a.iter().zip(b) {
            let d = x.abs_diff(y);
            sum += u64::from(d);
            max_abs = max_abs.max(d);
            differs |= d != 0;
        }
        changed += usize::from(differs);
    }
    if changed == 0 {
        return ImageChange::Same;
    }
    let total = old.pixels.len() / 4;
    ImageChange::Pixels {
        mean_abs: sum as f64 / (total * 4) as f64,
        max_abs,
        changed,
        total,
    }
}

/// A one-line description of a change for the report. PNGs are compared pixel by pixel;
/// anything else (or a PNG that cannot be decoded) is described by its size.
pub fn describe(path: &str, change: Change, old: Option<&[u8]>, new: Option<&[u8]>) -> String {
    let is_png = path.to_ascii_lowercase().ends_with(".png");
    let image = |bytes: Option<&[u8]>| bytes.filter(|_| is_png).and_then(|b| decode_png(b).ok());
    let len = |bytes: Option<&[u8]>| bytes.map_or(0, <[u8]>::len);
    match change {
        Change::Added => match image(new) {
            Some(i) => format!("{}x{} image, {} bytes", i.width, i.height, len(new)),
            None => format!("{} bytes", len(new)),
        },
        Change::Deleted => format!("{} bytes", len(old)),
        Change::Modified => match (image(old), image(new)) {
            (Some(a), Some(b)) => match compare_images(&a, &b) {
                ImageChange::Same => "re-encoded, pixels identical".to_owned(),
                ImageChange::Size { old, new } => {
                    format!("size changed {}x{} -> {}x{}", old.0, old.1, new.0, new.1)
                }
                ImageChange::Pixels {
                    mean_abs,
                    max_abs,
                    changed,
                    total,
                } => format!(
                    "mean abs diff {mean_abs:.2}/255, max {max_abs}, {changed} of {total} pixels changed ({:.1}%)",
                    changed as f64 * 100.0 / total as f64
                ),
            },
            _ => format!("{} -> {} bytes", len(old), len(new)),
        },
    }
}

/// The review report: one line per changed file, then what to do with it.
pub fn render_report(rows: &[(Entry, String)]) -> String {
    if rows.is_empty() {
        return "No golden changes.\n".to_owned();
    }
    let mut text = format!("{} golden file(s) changed:\n", rows.len());
    for (entry, detail) in rows {
        text.push_str(&format!(
            "  {:<9} {}  {detail}\n",
            entry.change.label(),
            entry.path
        ));
    }
    text.push_str(&format!(
        "Review the files (open the images), commit the ones you accept and restore the rest with `git checkout -- {GOLDEN_DIR}`.\n"
    ));
    text
}

/// The changed golden files of the repository at `root`, each with its description.
///
/// # Errors
/// If `git` cannot be run.
pub fn changes(root: &str) -> Result<Vec<(Entry, String)>> {
    let status = git(
        Some(root),
        &[
            "status",
            "--porcelain",
            "--untracked-files=all",
            "--",
            GOLDEN_DIR,
        ],
    )?;
    let mut rows = Vec::new();
    for entry in parse_status(&String::from_utf8_lossy(&status), GOLDEN_DIR) {
        let new = (entry.change != Change::Deleted)
            .then(|| std::fs::read(Path::new(root).join(&entry.path)).ok())
            .flatten();
        let old = (entry.change != Change::Added)
            .then(|| git(Some(root), &["show", &format!("HEAD:{}", entry.path)]).ok())
            .flatten();
        let detail = describe(&entry.path, entry.change, old.as_deref(), new.as_deref());
        rows.push((entry, detail));
    }
    Ok(rows)
}

/// Regenerate the goldens: run every golden test target with `UPDATE_GOLDEN=1`.
///
/// # Errors
/// If `cargo` cannot be run or a test target fails (a missing GPU adapter skips the test, it
/// does not fail it, and then nothing is regenerated).
pub fn update(root: &str) -> Result<()> {
    for (package, test) in GOLDEN_TESTS {
        println!("golden: regenerating with `cargo test -p {package} --test {test}`");
        let status = Command::new("cargo")
            .args(["test", "-p", package, "--test", test])
            .env("UPDATE_GOLDEN", "1")
            .current_dir(root)
            .status()
            .with_context(|| format!("failed to run cargo test -p {package}"))?;
        if !status.success() {
            bail!("cargo test -p {package} --test {test} failed");
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn png_bytes(width: u32, height: u32, pixels: &[u8]) -> Vec<u8> {
        let mut out = Vec::new();
        let mut enc = png::Encoder::new(&mut out, width, height);
        enc.set_color(png::ColorType::Rgba);
        enc.set_depth(png::BitDepth::Eight);
        enc.write_header()
            .unwrap()
            .write_image_data(pixels)
            .unwrap();
        out
    }

    fn solid(width: u32, height: u32, rgba: [u8; 4]) -> Vec<u8> {
        rgba.iter()
            .copied()
            .cycle()
            .take((width * height * 4) as usize)
            .collect()
    }

    #[test]
    fn status_lines_become_entries_under_the_golden_folder_only() {
        let porcelain = " M testdata/golden/a.png\n\
                         ?? testdata/golden/new.png\n\
                         D  testdata/golden/gone.png\n\
                         A  testdata/golden/staged.png\n\
                         AM testdata/golden/both.png\n\
                         \x20M src/unrelated.rs\n\
                         R  testdata/golden/old.png -> testdata/golden/renamed.png\n\
                         ?? \"testdata/golden/with space.png\"\n";
        let entries = parse_status(porcelain, "testdata/golden");
        let got: Vec<(&str, Change)> = entries
            .iter()
            .map(|e| (e.path.as_str(), e.change))
            .collect();
        assert_eq!(
            got,
            [
                ("testdata/golden/a.png", Change::Modified),
                ("testdata/golden/new.png", Change::Added),
                ("testdata/golden/gone.png", Change::Deleted),
                ("testdata/golden/staged.png", Change::Added),
                ("testdata/golden/both.png", Change::Added),
                ("testdata/golden/old.png", Change::Deleted),
                ("testdata/golden/renamed.png", Change::Added),
                ("testdata/golden/with space.png", Change::Added),
            ]
        );
    }

    #[test]
    fn a_png_is_decoded_to_rgba_pixels() {
        let bytes = png_bytes(2, 1, &[1, 2, 3, 4, 5, 6, 7, 8]);
        let img = decode_png(&bytes).unwrap();
        assert_eq!((img.width, img.height), (2, 1));
        assert_eq!(img.pixels, [1, 2, 3, 4, 5, 6, 7, 8]);
        assert!(decode_png(b"not a png").is_err());
    }

    #[test]
    fn identical_images_have_no_difference() {
        let a = decode_png(&png_bytes(2, 2, &solid(2, 2, [9, 9, 9, 255]))).unwrap();
        assert_eq!(compare_images(&a, &a.clone()), ImageChange::Same);
    }

    #[test]
    fn one_changed_channel_is_measured_exactly() {
        let old = decode_png(&png_bytes(2, 2, &solid(2, 2, [0, 0, 0, 255]))).unwrap();
        let mut px = solid(2, 2, [0, 0, 0, 255]);
        px[0] = 10; // red of the first pixel
        let new = decode_png(&png_bytes(2, 2, &px)).unwrap();
        let ImageChange::Pixels {
            mean_abs,
            max_abs,
            changed,
            total,
        } = compare_images(&old, &new)
        else {
            panic!("expected a pixel difference");
        };
        assert_eq!((max_abs, changed, total), (10, 1, 4));
        assert!((mean_abs - 10.0 / 16.0).abs() < 1e-9, "{mean_abs}");
    }

    #[test]
    fn a_size_change_is_reported_as_such() {
        let a = decode_png(&png_bytes(2, 1, &solid(2, 1, [0; 4]))).unwrap();
        let b = decode_png(&png_bytes(1, 2, &solid(1, 2, [0; 4]))).unwrap();
        assert_eq!(
            compare_images(&a, &b),
            ImageChange::Size {
                old: (2, 1),
                new: (1, 2)
            }
        );
    }

    #[test]
    fn descriptions_say_what_a_reviewer_needs() {
        let black = png_bytes(2, 2, &solid(2, 2, [0, 0, 0, 255]));
        let mut px = solid(2, 2, [0, 0, 0, 255]);
        px[4] = 255;
        let changed = png_bytes(2, 2, &px);

        let added = describe("g/x.png", Change::Added, None, Some(&black));
        // The change label ("added", "deleted") is its own column in the report row, so the
        // description carries only the details.
        assert!(added.contains("2x2") && added.contains("bytes"), "{added}");
        let deleted = describe("g/x.png", Change::Deleted, Some(&black), None);
        assert_eq!(deleted, format!("{} bytes", black.len()));
        let same = describe("g/x.png", Change::Modified, Some(&black), Some(&black));
        assert!(same.contains("identical"), "{same}");
        let diff = describe("g/x.png", Change::Modified, Some(&black), Some(&changed));
        assert!(
            diff.contains("1 of 4 pixels") && diff.contains("max 255"),
            "{diff}"
        );
        let resized = describe(
            "g/x.png",
            Change::Modified,
            Some(&black),
            Some(&png_bytes(1, 1, &[0, 0, 0, 255])),
        );
        assert!(
            resized.contains("2x2") && resized.contains("1x1"),
            "{resized}"
        );
        let text = describe(
            "g/trace.txt",
            Change::Modified,
            Some(b"abc"),
            Some(b"abcdef"),
        );
        assert!(text.contains("3 -> 6 bytes"), "{text}");
        let broken = describe("g/bad.png", Change::Modified, Some(b"x"), Some(b"yy"));
        assert!(broken.contains("1 -> 2 bytes"), "{broken}");
    }

    #[test]
    fn the_report_lists_every_change_and_tells_the_reviewer_what_to_do() {
        let rows = vec![
            (
                Entry {
                    path: "testdata/golden/a.png".into(),
                    change: Change::Modified,
                },
                "mean abs diff 1.00/255".to_owned(),
            ),
            (
                Entry {
                    path: "testdata/golden/b.png".into(),
                    change: Change::Added,
                },
                "added".to_owned(),
            ),
        ];
        let text = render_report(&rows);
        assert!(text.contains("2 golden file(s) changed"), "{text}");
        assert!(
            text.contains("modified") && text.contains("testdata/golden/a.png"),
            "{text}"
        );
        assert!(
            text.contains("added") && text.contains("mean abs diff 1.00/255"),
            "{text}"
        );
        assert!(text.contains("git checkout -- testdata/golden"), "{text}");
        assert!(render_report(&[]).contains("No golden changes"));
    }
}
